from django.core.management.base import BaseCommand
from django.db import transaction
from apps.catalog.models import Category, Service
from apps.core.showcase import SERVICE_GROUPS

OFFERS = [('developpement-logiciel', 'donnees-bases-analyse', 'Bases de données et analyse de données', 'Conception et organisation de bases PostgreSQL, MySQL ou SQLite, préparation des données, requêtes SQL et tableaux de suivi. Le périmètre est défini selon vos données et les informations à exploiter.', 'Entreprises, ONG, institutions et équipes de projet'), ('developpement-logiciel', 'ia-etude-prototypage', 'Intelligence artificielle : étude et prototypage', 'Étude de faisabilité, préparation des données, développement de prototypes et évaluation de modèles d’intelligence artificielle. Les sujets avancés, notamment les données multimodales et de capteurs, sont traités dans un cadre de recherche ou de prototypage.', 'Organisations, équipes d’innovation et projets de recherche'), ('location-services-operationnels', 'location-espaces', 'Location de salles et d’espaces', 'Mise à disposition d’espaces pour les réunions, les formations, les ateliers et les événements. La disponibilité, la capacité, les équipements et le tarif sont confirmés avant la réservation.', 'Entreprises, formateurs, associations et institutions'), ('informatique-digital', 'maintenance-assistance', 'Maintenance et assistance informatique', 'Diagnostic des problèmes, maintenance préventive et corrective, installation de logiciels et configuration des postes. Les interventions et les modalités d’assistance sont précisées selon votre équipement et votre besoin.', 'Particuliers, professionnels et organisations'), ('informatique-digital', 'cloud-collaboration', 'Google Workspace et outils collaboratifs', 'Configuration de Google Workspace et des outils de travail en équipe, organisation des espaces partagés et accompagnement des utilisateurs. Les comptes, licences et éventuelles migrations sont précisés dans la proposition.', 'Entreprises, associations, ONG et équipes de projet'), ('informatique-digital', 'automatisation-ia', 'Automatisation des tâches et outils d’IA', 'Analyse des tâches répétitives, connexion des outils existants et mise en place d’automatisations adaptées à vos usages. L’utilisation d’outils d’intelligence artificielle est étudiée selon vos processus et les données concernées.', 'Professionnels, entreprises et organisations'), ('web-domaines-hebergement', 'creation-sites-web', 'Création de sites web', 'Conception et réalisation de sites vitrines et institutionnels pour présenter votre activité, vos services et vos contenus. Les fonctionnalités, les pages, la prise en main et les services associés sont précisés dans le devis.', 'Entrepreneurs, entreprises, associations, ONG et institutions'), ('web-domaines-hebergement', 'domaines-hebergement-emails', 'Noms de domaine, hébergement et e-mails professionnels', 'Accompagnement à la réservation et à la gestion de noms de domaine, choix d’un hébergement et configuration d’adresses e-mail professionnelles. Les ressources, les coûts récurrents et les conditions de renouvellement sont précisés dans l’offre.', 'Particuliers, professionnels et organisations'), ('web-domaines-hebergement', 'maintenance-sites', 'Maintenance et sauvegarde de sites web', 'Mises à jour, sauvegardes, vérifications de sécurité et assistance pour les sites web. La fréquence des opérations, les accès nécessaires et les conditions d’intervention sont définis selon le site.', 'Entreprises, organisations et propriétaires de sites web'), ('developpement-logiciel', 'applications-sur-mesure', 'Applications et logiciels sur mesure', 'Conception d’applications web, d’outils métier et de systèmes internes, avec bases de données et intégrations d’API selon les besoins. Les demandes d’applications mobiles font l’objet d’une étude technique préalable.', 'Entreprises, ONG, institutions et équipes de projet'), ('conseil', 'conseil-transformation-digitale', 'Conseil en transformation numérique', 'Analyse des besoins, état des lieux des outils et recommandations pour votre stratégie numérique, vos systèmes d’information et votre organisation. L’accompagnement peut inclure la définition et le suivi d’un projet.', 'Entrepreneurs, entreprises et organisations'), ('organisations', 'digitalisation-organisations', 'Déploiement numérique et accompagnement des équipes', 'Accompagnement à la mise en place des outils retenus pour votre organisation : configuration, organisation des données, prise en main et formation des utilisateurs. La prestation est définie selon les besoins de vos équipes.', 'PME, jeunes entreprises, associations, ONG, écoles et institutions')]
class Command(BaseCommand):
    help = 'Ajoute les offres initiales de la vitrine sans modifier les contenus existants.'
    def add_arguments(self, parser):
        parser.add_argument('--update-texts', action='store_true', help='Actualise les textes des offres initiales sans modifier les prix ni les statuts.')

    @transaction.atomic
    def handle(self, *args, **options):
        categories = {}
        for group in SERVICE_GROUPS:
            category, _ = Category.objects.get_or_create(slug=group['slug'], defaults={'name': group['name']})
            if options.get('update_texts'):
                category.name = group['name']
                category.save(update_fields=['name'])
            categories[group['slug']] = category
        count = 0
        for group, slug, title, description, audience in OFFERS:
            _, created = Service.objects.get_or_create(slug=slug, defaults={'category': categories[group], 'title': title, 'description': description, 'audience': audience, 'estimated_delivery': 'À définir après étude du besoin', 'conditions': 'Périmètre, délais, livrables et modalités précisés dans le devis.', 'pricing': 'quote', 'active': True})
            if options.get('update_texts') and not created:
                Service.objects.filter(slug=slug).update(category=categories[group], title=title, description=description, audience=audience)
            count += created
        self.stdout.write(self.style.SUCCESS(f'{count} offres créées. ' + ('Textes des offres initiales actualisés ; prix et statuts conservés.' if options.get('update_texts') else 'Contenus existants conservés.')))
